#!/usr/bin/env node
/**
 * PreToolUse hook (Edit|Write): guard the auto-generated route registry.
 *
 * `src/pages.config.js` is regenerated by the Base44 platform — hand-edits get
 * clobbered on the next sync. Per CLAUDE.md the ONLY editable value is
 * `mainPage`. This hook denies Edit/Write to that file UNLESS the edit is only
 * touching the `mainPage` line, so accidental structural edits are blocked but
 * an intentional landing-page change still goes through.
 *
 * Reads the hook payload as JSON on stdin and emits a PreToolUse permission
 * decision as JSON on stdout. Implemented in Node because `jq` is not installed.
 */
function readStdin() {
  return new Promise((resolve) => {
    let data = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk) => (data += chunk));
    process.stdin.on("end", () => resolve(data));
    setTimeout(() => resolve(data), 2000).unref?.();
  });
}

function allow() {
  process.exit(0);
}

function deny(reason) {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: reason,
      },
    }),
  );
  process.exit(0);
}

const raw = await readStdin();
let payload = {};
try {
  payload = JSON.parse(raw || "{}");
} catch {
  allow();
}

const input = payload?.tool_input || {};
const filePath = (input.file_path || "").replace(/\\/g, "/");

if (!/\/src\/pages\.config\.js$/.test(filePath)) allow();

// Allow edits that only adjust the `mainPage` value.
const touchesOnlyMainPage =
  payload?.tool_name === "Edit" &&
  /mainPage/.test(input.old_string || "") &&
  /mainPage/.test(input.new_string || "");

if (touchesOnlyMainPage) allow();

deny(
  "src/pages.config.js is auto-generated by Base44 and will be overwritten on the next sync. " +
    "Only the `mainPage` value is hand-editable. To add a page, create src/pages/<Name>.jsx " +
    "(auto-registered) and, if it needs a custom route, wire it into <Routes> in src/App.jsx instead.",
);
